  for(const side of [0,1])for(let j=0;j<7;j++){const x=side?1911-j*6:8+j*6;curve(u=>[x+Math.sin(u*3+t*.2)*4,196+u*488],j%2?ice:'#8ca1d9',.8,.25);if(j%2===0)light(u=>[x,196+u*488],ice,j*.12,.12,1.8);}
