  for(let j=0;j<8;j++){const age=(beat*.19+j*.14)%1,x=80+Math.sin(j*2.3)*age*64,y=433-age*106+age*age*116;c.save();c.globalAlpha*=Math.sin(age*Math.PI);star(x,y,.3+age*.3,j%2?ice:gold,age*4);c.restore();}
