  place(1450,1036,.76,.1,()=>{poly([[-40,20],[1,-58],[39,20]],metal([-40,-58,39,20],['#8c94d3','#49639a','#a58bc8','#364b7e']));disc(0,21,51,8,'#8094bd');star(1,-19,.4,gold,.2);});
